// terrain_rom.sv - the terrain map, 64 x 32 tiles, 4 bits per tile.
//
// Contents come from mem/map0.mem (generated by scripts/gen_map.py from
// maps/map0.txt). Address = {tile_y[4:0], tile_x[5:0]}.
//
// Two independent read ports on the same memory (one dual-port block RAM):
//   Port A: game logic asks "is this tile passable?" (game_ctrl)
//   Port B: the renderer reads the tile under the beam every clock (drawcon)
//
// Read latency: 1 clock on both ports (data appears on the edge after addr).
module terrain_rom
  import game_pkg::*;
#(
  parameter string INIT_FILE = "map0.mem"
)(
  input  logic                  clk,
  input  logic [MAP_ADDR_W-1:0] addr_a,
  output logic [TERRAIN_W-1:0]  data_a,
  input  logic [MAP_ADDR_W-1:0] addr_b,
  output logic [TERRAIN_W-1:0]  data_b
);

  (* rom_style = "block" *)
  logic [TERRAIN_W-1:0] mem [MAP_W * MAP_H];

  initial $readmemh(INIT_FILE, mem);

  always_ff @(posedge clk) begin
    data_a <= mem[addr_a];
    data_b <= mem[addr_b];
  end

endmodule
